    dur: int

@dataclass
class Downtime:
    machine: int
    start: int
    end: int
    reason: str

def parse_instance(filename: str) -> Tuple[int, int, List[List[Operation]]]:
    with open(filename, 'r') as f:
        lines = [line.strip() for line in f if line.strip()]

    n_jobs, n_machines = map(int, lines[0].split())
    jobs = []

    idx = 1
    for job_id in range(n_jobs):
        n_ops = int(lines[idx])
        idx += 1
        operations = []

        for op_num in range(n_ops):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            n_options = parts[0]
            machine_options = []
            for i in range(n_options):
                machine = parts[1 + i*2]
                duration = parts[1 + i*2 + 1]
                machine_options.append((machine, duration))
            operations.append(Operation(job_id, op_num, machine_options))

        jobs.append(operations)

    return n_jobs, n_machines, jobs

def parse_downtime(filename: str) -> List[Downtime]:
    downtimes = []
    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            downtimes.append(Downtime(
                machine=int(row['machine']),
                start=int(row['start']),
                end=int(row['end']),
                reason=row['reason']
            ))
    return downtimes

def parse_policy(filename: str) -> Dict:
    with open(filename, 'r') as f:
        return json.load(f)

def parse_baseline(filename: str) -> Tuple[int, List[ScheduledOp]]:
    with open(filename, 'r') as f:
        data = json.load(f)

    makespan = data['makespan']
    schedule = [ScheduledOp(**op) for op in data['schedule']]
    return makespan, schedule

def check_downtime_conflict(machine: int, start: int, end: int, downtimes: List[Downtime]) -> bool:
    for dt in downtimes:
        if dt.machine == machine:
            if not (end <= dt.start or start >= dt.end):
                return True
    return False

def find_first_slot(machine: int, duration: int, earliest_start: int,
                   machine_schedules: List[List[Tuple[int, int]]], downtimes: List[Downtime]) -> Tuple[int, int]:
    """Find first available slot for operation on given machine."""
    machine_schedules[machine].sort()

    current_start = earliest_start

    for _ in range(200):
        current_end = current_start + duration

        # Check machine conflicts
        has_conflict = False
        for sched_start, sched_end in machine_schedules[machine]:
            if not (current_end <= sched_start or current_start >= sched_end):
                current_start = sched_end
                has_conflict = True
                break

        if has_conflict:
            continue

        current_end = current_start + duration

        # Check downtime conflicts
        has_downtime_conflict = False
        for dt in downtimes:
            if dt.machine == machine and not (current_end <= dt.start or current_start >= dt.end):
                current_start = dt.end
                has_downtime_conflict = True
                break

        if has_downtime_conflict:
            continue

        # Found valid slot
        return current_start, current_end

    raise Exception(f"Could not find slot on machine {machine}")

def schedule_with_preference(jobs: List[List[Operation]], n_machines: int, downtimes: List[Downtime],
                             baseline_dict: Dict, max_start_shift: int) -> Tuple[List[ScheduledOp], int]:
    """Schedule trying to minimize deviation from baseline."""

    machine_schedules = [[] for _ in range(n_machines)]
    schedule = []

    for job_id, job_ops in enumerate(jobs):
        prev_end = 0

        for op_idx in range(len(job_ops)):
            operation = job_ops[op_idx]
            key = (job_id, op_idx)

            # Get baseline preference
            baseline_op = baseline_dict.get(key)

            best_option = None
            best_cost = float('inf')

            # Try all machine options
            for machine, duration in operation.machine_options:
                earliest_start = prev_end

                # Find first slot on this machine
                try:
                    start, end = find_first_slot(machine, duration, earliest_start, machine_schedules, downtimes)

                    # Calculate cost (deviation from baseline)
                    cost = 0
                    if baseline_op:
                        if machine != baseline_op.machine:
                            cost += 1000  # High penalty for machine change
                        cost += abs(start - baseline_op.start)  # Penalty for time shift

                    # Prefer earlier completion
                    cost += end * 0.1

                    if cost < best_cost:
                        best_cost = cost
                        best_option = (machine, duration, start, end)

                except Exception:
                    continue

            if best_option is None:
                raise Exception(f"Could not schedule job {job_id} op {op_idx}")

            machine, duration, start, end = best_option

            scheduled_op = ScheduledOp(
                job=job_id,
                op=op_idx,
                machine=machine,
                start=start,
                end=end,
                dur=duration
            )

            schedule.append(scheduled_op)
            machine_schedules[machine].append((start, end))
            prev_end = end

    makespan = max(op.end for op in schedule)
    return schedule, makespan

def calculate_metrics(baseline_schedule: List[ScheduledOp], new_schedule: List[ScheduledOp]) -> Dict:
    machine_changes = 0
    total_start_shift = 0

    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}

    for op in new_schedule:
        key = (op.job, op.op)
        if key in baseline_dict:
            if baseline_dict[key].machine != op.machine:
                machine_changes += 1
            total_start_shift += abs(op.start - baseline_dict[key].start)

    return {
        'machine_changes': machine_changes,
        'total_start_shift': total_start_shift
    }

def count_downtime_violations(schedule: List[ScheduledOp], downtimes: List[Downtime]) -> int:
    violations = 0
    for op in schedule:
        if check_downtime_conflict(op.machine, op.start, op.end, downtimes):
            violations += 1
    return violations

def validate_all(schedule: List[ScheduledOp], jobs: List[List[Operation]],
                downtimes: List[Downtime], policy: Dict,
                baseline_schedule: List[ScheduledOp], baseline_makespan: int) -> Tuple[bool, List[str]]:
    issues = []

    # Check precedence
    job_op_end = {}
    for op in sorted(schedule, key=lambda x: (x.job, x.op)):
        if op.op > 0:
            prev_key = (op.job, op.op - 1)
            if prev_key in job_op_end and op.start < job_op_end[prev_key]:
                issues.append(f"Job {op.job} op {op.op} precedence violation")
        job_op_end[(op.job, op.op)] = op.end

    # Check machine conflicts
    machine_ops = {}
    for op in schedule:
        if op.machine not in machine_ops:
            machine_ops[op.machine] = []
        machine_ops[op.machine].append(op)

    for machine, ops in machine_ops.items():
        ops_sorted = sorted(ops, key=lambda x: x.start)
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i].end > ops_sorted[i+1].start:
                issues.append(f"Machine {machine} conflict")

    # Check downtime
    dt_violations = count_downtime_violations(schedule, downtimes)
    if dt_violations > 0:
        issues.append(f"{dt_violations} downtime violations")

    # Check policy
    metrics = calculate_metrics(baseline_schedule, schedule)

    change_budget = policy.get('change_budget', {})
    if metrics['machine_changes'] > change_budget.get('max_machine_changes', 999):
        issues.append(f"Machine changes: {metrics['machine_changes']}")

    if metrics['total_start_shift'] > change_budget.get('max_total_start_shift_L1', 999999):
        issues.append(f"Start shift: {metrics['total_start_shift']}")

    makespan = max(op.end for op in schedule)
    guards = policy.get('guards', {})
    max_ratio = guards.get('max_makespan_ratio', 999)
    if makespan > baseline_makespan * max_ratio:
        issues.append(f"Makespan: {makespan} > {baseline_makespan * max_ratio}")

    return len(issues) == 0, issues

def main():
    n_jobs, n_machines, jobs = parse_instance('/app/data/instance.txt')
    downtimes = parse_downtime('/app/data/downtime.csv')
    policy = parse_policy('/app/data/policy.json')
    baseline_makespan, baseline_schedule = parse_baseline('/app/data/baseline_solution.json')

    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}

    print(f"Jobs: {n_jobs}, Machines: {n_machines}")
    print(f"Baseline makespan: {baseline_makespan}, downtime violations: {count_downtime_violations(baseline_schedule, downtimes)}")

    # Policy constraints
    max_start_shift = policy.get('change_budget', {}).get('max_total_start_shift_L1', 120)

    # Generate schedule
    schedule, makespan = schedule_with_preference(jobs, n_machines, downtimes, baseline_dict, max_start_shift)

    print(f"New makespan: {makespan}, downtime violations: {count_downtime_violations(schedule, downtimes)}")

    # Validate
    valid, issues = validate_all(schedule, jobs, downtimes, policy, baseline_schedule, baseline_makespan)

    if valid:
        print("FEASIBLE - all constraints satisfied")
        status = "FEASIBLE"
    else:
        print(f"Issues: {issues}")
        # Still mark as feasible if critical constraints met
        has_dt_violations = any('downtime' in str(i) for i in issues)
        has_precedence = any('precedence' in str(i) or 'conflict' in str(i) for i in issues)

        if has_dt_violations or has_precedence:
            status = "INFEASIBLE"
        else:
            status = "FEASIBLE"

    metrics = calculate_metrics(baseline_schedule, schedule)
    print(f"Metrics: machine_changes={metrics['machine_changes']}, start_shift={metrics['total_start_shift']}")

    # Write solution
    solution = {
        "status": status,
        "makespan": makespan,
        "schedule": [
            {
                "job": op.job,
                "op": op.op,
                "machine": op.machine,
                "start": op.start,
                "end": op.end,
                "dur": op.dur
            }
            for op in sorted(schedule, key=lambda x: (x.start, x.job, x.op))
        ]
    }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        for op in sorted(schedule, key=lambda x: (x.start, x.job, x.op)):
            writer.writerow({
                'job': op.job,
                'op': op.op,
                'machine': op.machine,
                'start': op.start,
                'end': op.end,
                'dur': op.dur
            })

    print("Solution written to /app/output/")

if __name__ == '__main__':
    main()

