            n_options = parts[0]
            machine_options = []
            for i in range(n_options):
                machine = parts[1 + i*2]
                duration = parts[1 + i*2 + 1]
                machine_options.append((machine, duration))
            operations.append(Operation(job_id, op_num, machine_options))

        jobs.append(operations)

    return n_jobs, n_machines, jobs

def parse_downtime(filename: str):
    downtimes = []
    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            downtimes.append(Downtime(
                int(row['machine']),
                int(row['start']),
                int(row['end'])
            ))
    return downtimes

def parse_policy(filename: str):
    with open(filename, 'r') as f:
        return json.load(f)

def parse_baseline(filename: str):
    with open(filename, 'r') as f:
        data = json.load(f)
    return data['makespan'], [ScheduledOp(**op) for op in data['schedule']]

def has_downtime_conflict(machine: int, start: int, end: int, downtimes: List[Downtime]) -> bool:
    for dt in downtimes:
        if dt.machine == machine and not (end <= dt.start or start >= dt.end):
            return True
    return False

def schedule_greedy(jobs, n_machines, downtimes, baseline_dict):
    """Greedy scheduling with smart machine selection."""
    machine_end_time = [0] * n_machines
    schedule = []
    job_end_time = {}

    for job_id, job_ops in enumerate(jobs):
        for op_idx, operation in enumerate(job_ops):
            # Earliest start is after previous op in same job
            earliest_start = job_end_time.get((job_id, op_idx - 1), 0) if op_idx > 0 else 0

            best = None
            best_score = float('inf')

            baseline_op = baseline_dict.get((job_id, op_idx))

            # Try each machine option
            for machine, duration in operation.machine_options:
                # Find earliest feasible time on this machine
                start = max(earliest_start, machine_end_time[machine])

                # Avoid downtime
                for _ in range(50):  # Max attempts
                    end = start + duration

                    if has_downtime_conflict(machine, start, end, downtimes):
                        # Try before downtime or after downtime
                        options = []
                        for dt in downtimes:
                            if dt.machine == machine:
                                # Before downtime
                                if earliest_start + duration <= dt.start:
                                    options.append(max(earliest_start, machine_end_time[machine]))
                                # After downtime
                                options.append(max(dt.end, earliest_start))

                        if options:
                            start = min(options, key=lambda x: x)
                        else:
                            # Move past all downtimes
                            for dt in downtimes:
                                if dt.machine == machine:
                                    start = max(start, dt.end)
                    else:
                        break

                end = start + duration

