                if has_downtime_conflict(machine, start, end, downtimes):
                    continue

                # Score this option
                score = end  # Prefer early completion

                # Bonus for matching baseline machine
                if baseline_op and machine == baseline_op.machine:
                    score -= 50

                if score < best_score:
                    best_score = score
                    best = (machine, duration, start, end)

            if not best:
                raise Exception(f"Cannot schedule Job {job_id} Op {op_idx}")

            machine, duration, start, end = best

            op = ScheduledOp(job_id, op_idx, machine, start, end, duration)
            schedule.append(op)

            machine_end_time[machine] = end
            job_end_time[(job_id, op_idx)] = end

    return schedule, max(op.end for op in schedule)

