    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}
    machine_changes = 0
    start_shift = 0

    for op in new_schedule:
        key = (op.job, op.op)
        if key in baseline_dict:
            if baseline_dict[key].machine != op.machine:
                machine_changes += 1
            start_shift += abs(op.start - baseline_dict[key].start)

    return machine_changes, start_shift

