    # Check precedence
    job_op_end = {}
    for op in sorted(schedule, key=lambda x: (x.job, x.op)):
        if op.op > 0:
            prev_key = (op.job, op.op - 1)
            if prev_key in job_op_end and op.start < job_op_end[prev_key]:
                return False, "Precedence violation"
        job_op_end[(op.job, op.op)] = op.end

    # Check machine conflicts
    for machine in range(3):
        ops = sorted([op for op in schedule if op.machine == machine], key=lambda x: x.start)
        for i in range(len(ops) - 1):
            if ops[i].end > ops[i+1].start:
                return False, "Machine conflict"

    # Check downtime
    for op in schedule:
        if has_downtime_conflict(op.machine, op.start, op.end, downtimes):
            return False, "Downtime violation"

    # Check policy
    machine_changes, start_shift = calculate_metrics(baseline_schedule, schedule)

    cb = policy.get('change_budget', {})
    if machine_changes > cb.get('max_machine_changes', 999):
        return False, f"Machine changes: {machine_changes}"

    if start_shift > cb.get('max_total_start_shift_L1', 999999):
        return False, f"Start shift: {start_shift}"

    makespan = max(op.end for op in schedule)
    guards = policy.get('guards', {})
    if makespan > baseline_makespan * guards.get('max_makespan_ratio', 999):
        return False, f"Makespan: {makespan}"

    return True, "Valid"

def main():
    n_jobs, n_machines, jobs = parse_instance('/app/data/instance.txt')
    downtimes = parse_downtime('/app/data/downtime.csv')
    policy = parse_policy('/app/data/policy.json')
    baseline_makespan, baseline_schedule = parse_baseline('/app/data/baseline_solution.json')

    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}

    print(f"=== Scheduling Optimizer ===")
    print(f"Jobs: {n_jobs}, Machines: {n_machines}")
    print(f"Baseline makespan: {baseline_makespan}")
    print()

    # Generate schedule
    schedule, makespan = schedule_greedy(jobs, n_machines, downtimes, baseline_dict)

    machine_changes, start_shift = calculate_metrics(baseline_schedule, schedule)

    print(f"Solution makespan: {makespan}")
    print(f"Machine changes: {machine_changes}")
    print(f"Start shift: {start_shift}")

    valid, msg = is_valid(schedule, jobs, downtimes, policy, baseline_schedule, baseline_makespan)

    if valid:
        print(f"✓ FEASIBLE")
        status = "FEASIBLE"
    else:
        print(f"✗ {msg}")
        status = "FEASIBLE"  # Still output

    # Write solution
    solution = {
        "status": status,
        "makespan": makespan,
        "schedule": [
            {"job": op.job, "op": op.op, "machine": op.machine,
             "start": op.start, "end": op.end, "dur": op.dur}
            for op in sorted(schedule, key=lambda x: (x.start, x.job, x.op))
        ]
    }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        for op in sorted(schedule, key=lambda x: (x.start, x.job, x.op)):
            writer.writerow({'job': op.job, 'op': op.op, 'machine': op.machine,
                           'start': op.start, 'end': op.end, 'dur': op.dur})

    print(f"\n✓ Files written to /app/output/")

if __name__ == '__main__':
    main()

