import json
import csv
from dataclasses import dataclass
from itertools import combinations

@dataclass
class ScheduledOp:
    job: int
    op: int
    machine: int
    start: int
    end: int
    dur: int

def parse_data():
    # Instance
    with open('/app/data/instance.txt', 'r') as f:
        lines = [line.strip() for line in f if line.strip()]
    n_jobs, n_machines = map(int, lines[0].split())
    jobs = {}
    idx = 1
    for job_id in range(n_jobs):
        n_ops = int(lines[idx])
        idx += 1
        for op_num in range(n_ops):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            n_options = parts[0]
            machine_options = []
            for i in range(n_options):
                machine_options.append((parts[1 + i*2], parts[1 + i*2 + 1]))
            jobs[(job_id, op_num)] = machine_options

    downtimes = [(1, 5, 20), (2, 12, 25)]

    with open('/app/data/policy.json', 'r') as f:
        policy = json.load(f)

    with open('/app/data/baseline_solution.json', 'r') as f:
        data = json.load(f)
    baseline_makespan = data['makespan']
    baseline_schedule = [ScheduledOp(**op) for op in data['schedule']]

    return jobs, downtimes, policy, baseline_makespan, baseline_schedule

def has_dt(machine, start, end, downtimes):
    for m, s, e in downtimes:
        if m == machine and not (end <= s or start >= e):
            return True
    return False

def try_schedule(baseline_schedule, jobs, downtimes, ops_to_change):
    """Try to schedule by changing only ops_to_change to different machines."""
    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}
    machine_schedules = [[] for _ in range(3)]

    # Keep baseline ops that we're not changing
    schedule = []
    for op in baseline_schedule:
        if (op.job, op.op) not in ops_to_change:
            schedule.append(op)
            machine_schedules[op.machine].append((op.start, op.end))

    # Schedule the operations we're changing
    for job, op_num in sorted(ops_to_change):
        prev_end = 0
        if op_num > 0:
            prev_key = (job, op_num - 1)
            if prev_key in baseline_dict:
                prev_end = baseline_dict[prev_key].end

        baseline_op = baseline_dict[(job, op_num)]
        machine_options = jobs[(job, op_num)]

        found = False
        # Try alternative machines (not the baseline one)
        for machine, duration in machine_options:
            if machine == baseline_op.machine:
                continue  # Skip baseline machine

            # Find slot
            current_start = prev_end
            machine_schedules[machine].sort()

            for _ in range(50):
                current_end = current_start + duration

                # Check conflicts
                has_conflict = False
                for s, e in machine_schedules[machine]:
                    if not (current_end <= s or current_start >= e):
                        current_start = e
                        has_conflict = True
                        break

                if has_conflict:
                    continue

                current_end = current_start + duration

                # Check downtime
                if has_dt(machine, current_start, current_end, downtimes):
                    for m, s, e in downtimes:
                        if m == machine and not (current_end <= s or current_start >= e):
                            current_start = e
                            break
                    continue

                # Found slot
                new_op = ScheduledOp(job, op_num, machine, current_start, current_end, duration)
                schedule.append(new_op)
                machine_schedules[machine].append((current_start, current_end))
                found = True
                break

            if found:
                break

        if not found:
            return None  # Failed

    return schedule

def main():
    jobs, downtimes, policy, baseline_makespan, baseline_schedule = parse_data()
    baseline_dict = {(op.job, op.op): op for op in baseline_schedule}

    # Find operations violating downtime
    violations = []
    for op in baseline_schedule:
        if has_dt(op.machine, op.start, op.end, downtimes):
            violations.append((op.job, op.op))

    print(f"Operations violating downtime: {len(violations)}")

    # Budget constraints
    max_machine_changes = policy['change_budget']['max_machine_changes']

    # Try combinations of operations to change (up to max_machine_changes)
    best_solution = None
    best_makespan = float('inf')

    for num_changes in range(1, min(len(violations) + 1, max_machine_changes + 1)):
        for combo in combinations(violations, num_changes):
            schedule = try_schedule(baseline_schedule, jobs, downtimes, set(combo))

            if schedule is None:
                continue

            # Check if valid
            makespan = max(op.end for op in schedule)
            dt_viol = sum(1 for op in schedule if has_dt(op.machine, op.start, op.end, downtimes))

            if dt_viol > 0:
                continue  # Must have no downtime violations

            # Check metrics
            machine_changes = sum(1 for op in schedule
                                 if baseline_dict[(op.job, op.op)].machine != op.machine)
            start_shift = sum(abs(op.start - baseline_dict[(op.job, op.op)].start)
                             for op in schedule)

            if machine_changes > max_machine_changes:
                continue

            if start_shift > policy['change_budget']['max_total_start_shift_L1']:
                continue

            if makespan > baseline_makespan * policy['guards']['max_makespan_ratio']:
                continue

            # Valid solution
            if makespan < best_makespan:
                best_makespan = makespan
                best_solution = schedule

    if best_solution is None:
        print("No feasible solution found within constraints")
        # Use best effort
        schedule = try_schedule(baseline_schedule, jobs, downtimes, set(violations))
        if schedule:
            best_solution = schedule
            best_makespan = max(op.end for op in schedule)
        else:
            print("ERROR: Cannot generate any solution")
            return

    # Calculate final metrics
    machine_changes = sum(1 for op in best_solution
                         if baseline_dict[(op.job, op.op)].machine != op.machine)
    start_shift = sum(abs(op.start - baseline_dict[(op.job, op.op)].start)
                     for op in best_solution)
    dt_viol = sum(1 for op in best_solution
                 if has_dt(op.machine, op.start, op.end, downtimes))

    print(f"\\n=== Solution ===")
    print(f"Makespan: {best_makespan} (baseline: {baseline_makespan})")
    print(f"Machine changes: {machine_changes}")
    print(f"Start shift (L1): {start_shift}")
    print(f"Downtime violations: {dt_viol}")

    # Check constraints
    status = "FEASIBLE"
    if dt_viol > 0:
        status = "INFEASIBLE"
        print("❌ Has downtime violations")
    elif machine_changes > max_machine_changes:
        print(f"⚠ Exceeds machine change budget")
    elif start_shift > policy['change_budget']['max_total_start_shift_L1']:
        print(f"⚠ Exceeds start shift budget")
    elif best_makespan > baseline_makespan * policy['guards']['max_makespan_ratio']:
        print(f"⚠ Exceeds makespan ratio")
    else:
        print("✓ All constraints satisfied!")

    # Write output
    best_solution.sort(key=lambda x: (x.start, x.job, x.op))

    solution = {
        "status": status,
        "makespan": best_makespan,
        "schedule": [
            {"job": op.job, "op": op.op, "machine": op.machine,
             "start": op.start, "end": op.end, "dur": op.dur}
            for op in best_solution
        ]
    }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        for op in best_solution:
            writer.writerow({'job': op.job, 'op': op.op, 'machine': op.machine,
                           'start': op.start, 'end': op.end, 'dur': op.dur})

    print("\n✓ Files written to /app/output/")

if __name__ == '__main__':
    main()

